/**
 * exemples-autres-familles.ts — Ateliers 3 à 5 (sources de risque, parties prenantes, actions élémentaires, mesures
 * sur l'écosystème, mesures) pour les familles qui servent les autres activités d'un groupe multi-activités : banque de
 * détail (dont réseau de guichets tenu par une autre entité), numérique (services de confiance, identité, coffre-fort),
 * télécoms (opérateur virtuel) et administration publique (accueil de services publics en guichet partagé).
 *
 * Même format que `exemples-protection-sociale.ts` (pack postal, lot L7) : textes ×5 dans la donnée, `profs` =
 * sous-profession, éléments sans `profs` = socle de la famille. Exemples GÉNÉRIQUES : aucune entreprise réelle n'est
 * citée. Suggestions à qualifier, contenu « à relire par un expert du secteur ». Module pur → testé.
 */
import type { ExtItem, Tr } from '@/lib/exemples-sectoriels-ext'

const L = (fr: string, en: string, de: string, es: string, it: string): Tr => [fr, en, de, es, it]
type P = readonly string[] | null
type Fam = 'finance' | 'numerique' | 'telecom' | 'public'
const mk = (famille: Fam, category: ExtItem['category'], profs: P, data: Record<string, unknown>): ExtItem => ({ famille, category, ...(profs ? { profs } : {}), data })
const er = (f: Fam, profs: P, description: Tr, impacts: Tr[], graviteDefaut: number) => mk(f, 'evenementsRedoutes', profs, { description, impacts, graviteDefaut })
const sr = (f: Fam, profs: P, nom: Tr, categorie: string, description: Tr, motivation: Tr, ressources: Tr, pertinenceDefaut: number) =>
  mk(f, 'sourcesRisque', profs, { nom, categorie, description, motivation, ressources, pertinenceDefaut })
const pp = (f: Fam, profs: P, nom: Tr, type: string, dependance: number, penetration: number, maturite: number, confiance: number) =>
  mk(f, 'partiesPrenantes', profs, { nom, type, dependance, penetration, maturite, confiance })
const ae = (f: Fam, profs: P, type: string, attack: string, nom: Tr, description: Tr) => mk(f, 'actionsElementaires', profs, { type, attack, nom, description })
const me = (f: Fam, profs: P, mesure: Tr, type: 'ORGANISATIONNELLE' | 'TECHNIQUE' | 'DETECTIVE', iso27005: string, description: Tr) =>
  mk(f, 'mesuresEcosysteme', profs, { mesure, type, iso27005, description })
const ms = (f: Fam, profs: P, nom: Tr, description: Tr, type: 'ORGANISATIONNELLE' | 'TECHNIQUE' | 'DETECTIVE', categorieEbios: 'GOUVERNANCE' | 'PROTECTION' | 'DEFENSE' | 'RESILIENCE', prioriteDefaut: 1 | 2 | 3, references?: string[]) =>
  mk(f, 'mesures', profs, { nom, description, type, categorieEbios, prioriteDefaut, ...(references ? { references } : {}) })

